#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    cin >> n >> k;

    int available = 0;
    for (int day = 1; day <= n; ++day) {
        int candies;
        cin >> candies;
        available += candies;

        int eaten = min(8, available);
        available -= eaten;
        k -= eaten;

        if (k <= 0) {
            cout << day << '\n';
            return 0;
        }
    }

    cout << -1 << '\n';
    return 0;
}

